insert into public.abe_auflagen_kuerzel (kuerzel, text, source)
values
  ('10B', 'Die mindestens erforderlichen Geschwindigkeitsbereiche der zu verwendenden Reifen sind unter Berücksichtigung der Loadindexe, mit Ausnahme der Reifen mit M+S-Profil, den Fahrzeugpapieren zu entnehmen, soweit im Verwendungsbereich keine Abweichungen festgelegt sind.', 'seed'),
  ('11A', 'Der vorschriftsmäßige Zustand des Fahrzeuges ist durch einen amtlich anerkannten Sachverständigen oder Prüfer für den Kraftfahrzeugverkehr oder einen Prüfingenieur einer Überwachungsorganisation oder einen Angestellten nach Abschnitt 4 der Anlage VIIIb zur StVZO unter Angabe von FAHRZEUGHERSTELLER, FAHRZEUGTYP und FAHRZEUGIDENTIFIZIERUNGSNUMMER auf einem Nachweis entsprechend dem im Beispielkatalog zum §19 StVZO veröffentlichten Muster bescheinigen zu lassen.', 'seed'),
  ('11B', 'Wird eine in diesem Gutachten aufgeführte Reifengröße verwendet, die nicht bereits in der Fahrzeuggenehmigung für diesen Fahrzeug-Typ/ -Variante/ -Version bzw. Fahrzeugausführung genannt ist, so sind die Angaben über die Reifengrößen in den Fahrzeugpapieren bei der nächsten Befassung mit den Fahrzeugpapieren durch die Zulassungsstelle unter Vorlage der Allgemeinen Betriebserlaubnis bzw. der Abnahmebestätigung nach §19 Abs. 3 der StVZO berichtigen zu lassen. Diese Berichtigung ist dann nicht erforderlich, wenn die ABE des Sonderrades eine Freistellung von der Pflicht zur Berichtigung der Fahrzeugpapiere enthält.', 'seed'),
  ('11G', 'Die Brems-, Lenkungsaggregate und das Fahrwerk mit Ausnahme von Sonder-Fahrwerksfedern müssen, sofern diese durch keine weiteren Auflagen berührt werden, dem Serienstand entsprechen. Für die Sonder-Fahrwerksfedern muß eine Allgemeine Betriebserlaubnis oder ein Teilegutachten vorliegen;', 'seed'),
  ('11H', 'Wird das serienmäßige Ersatzrad verwendet, soll mit mäßiger Geschwindigkeit und nicht länger als erforderlich gefahren werden. Hierbei müssen die serienmäßigen Befestigungsteile verwendet werden. Bei Fahrzeugausführungen mit Allradantrieb ist bei Verwendung des Ersatzrades darauf zu achten, daß nur Reifen mit gleich großem Abrollumfang zulässig sind.', 'seed'),
  ('12A', 'Die Verwendung von Schneeketten ist nicht möglich, es sei denn, dass für den hier aufgeführten Fahrzeugtyp eine weitere Umrüstmöglichkeit im Gutachten aufgeführt ist. Für diese Umrüstung mit der Einschränkung in Spalte Auflagen "Reifen mit Schneeketten" sind die dort aufgeführten Auflagen und Hinweise zu beachten.', 'seed'),
  ('166', 'Das Sonderrad (gepr. Radlast) ist in Verbindung mit dieser Reifengröße nur zulässig bis zu einer zul. Achslast von 1660 kg. Eine erhöhte zulässige Achslast bei Anhängerbetrieb (siehe Ziff. 33 zu Ziff. 16 h bzw. Feld 22 zu Feld 7.1-8.3 in den Fahrzeugpapieren) ist zu beachten.', 'seed'),
  ('22I', 'Durch Anlegen der hinteren Radhausausschnittkanten und Kunststoffinnenkotflügel über die gesamte Radhausausschnittkantenlänge ist die Freigängigkeit der Rad/Reifen-Kombination unter Berücksichtigung der maximal zulässigen Betriebsbreite nach ETRTO bzw. WdK (1,04 fache Nennbreite des Reifens) herzustellen.', 'seed'),
  ('245', 'Die Radabdeckung an Achse 1 ist durch Ausstellen der Frontschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 30 Grad vor der Radmitte herzustellen. Je nach Rüstzustand des Fahrzeuges (z. B. Fahrzeugtieferlegung, Radabdeckungsverbreiterung, usw.) kann es möglich sein, dass die Radabdeckung ausreichend ist. Die gesamte Breite der Rad/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('248', 'Die Radabdeckung an Achse 2 ist durch Ausstellen der Heckschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 50 Grad hinter der Radmitte herzustellen. Je nach Rüstzustand des Fahrzeuges (z. B. Fahrzeugtieferlegung, Radabdeckungsverbreiterung, usw.) kann es möglich sein, dass die Radabdeckung ausreichend ist. Die gesamte Breite der Rad/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('270', 'Durch Aufweiten bzw. Ausstellen der hinteren Radhäuser im Bereich der Radaußenseite über die gesamte Radhausausschnittkantenlänge um 8,0 mm ist eine ausreichende Freigängigkeit der Rad/Reifen-Kombination unter Berücksichtigung der maximal zulässigen Betriebsbreite nach ETRTO bzw. WdK (1,04 fache Nennbreite des Reifens) herzustellen.', 'seed'),
  ('4AC', 'Die Verwendung des vom Fahrzeughersteller verbauten Reifendruck Kontrollsystems mit Sensoren Art. Nr.: 10 10 048 (nur wenn auch original verbaut) ist zulässig. Das System muss gemäß den Herstellerangaben kalibriert werden. Alternativ kann ein geeignetes Nachrüstkontrollsystem verwendet werden.', 'seed'),
  ('4FN', 'Die Verwendung des vom Fahrzeughersteller verbauten Reifendruck Kontrollsystems mit Sensoren Art. Nr.: 133 48 3 93 (nur wenn auch original verbaut) ist nicht zulässig. Es kann ein geeignetes Nachrüst-Kontrollsystem verwendet werden.', 'seed'),
  ('4HY', 'Die Verwendung des vom Fahrzeughersteller verbauten Reifendruck Kontrollsystems mit Sensoren Art. Nr.: 10 10 028 (nur wenn auch original verbaut) ist nicht zulässig. Es kann ein geeignetes Nachrüstkontrollsystem verwendet werden.', 'seed'),
  ('51A', 'Der vom Fahrzeughersteller (siehe Betriebsanleitung oder Reifenfülldruckhinweis am Fahrzeug) bzw. Reifenhersteller vorgeschriebene Reifenfülldruck ist zu beachten. Die Verwendung von Reifen mit Notlaufeigenschaften ist laut Hersteller nur mit Reifenfülldrucküberwachungssystem zulässig.', 'seed'),
  ('52J', 'Diese Reifengröße ist nur mit M+S-Profil zulässig.', 'seed'),
  ('573', 'Die Verwendung unterschiedlicher Reifengrößen an Vorder- und Hinterachse ist an Fahrzeugen mit Allradantrieb nur zulässig, wenn deren Abrollumfänge gleich sind. Es ist eine Bestätigung des Reifenherstellers über die tatsächlichen Abrollumfänge erforderlich, es wird empfohlen den Nachweis der Eignung bei den Fahrzeugpapieren mitzuführen. Alle an ein und derselben Achse montierten Reifen müssen vom gleichen Reifentyp sein.', 'seed'),
  ('71C', 'Zum Auswuchten der Sonderräder dürfen an der Felgeninnenseite nur Klebegewichte angebracht werden.', 'seed'),
  ('71K', 'Zum Auswuchten der Sonderräder dürfen an der Felgenaußenseite nur Klebegewichte unterhalb des Tiefbetts angebracht werden.', 'seed'),
  ('721', 'Es ist nur die Verwendung von Gummiventilen oder Metallschraubventilen mit Überwurfmutter von außen, die weitgehend den Normen (DIN, E.T.R.T.O. bzw. Tire and Rim) entsprechen und die für einen Ventilloch-Nenndurchmesser von 11,3 mm geeignet sind, zulässig. Das Ventil darf nicht über den Felgenrand hinausragen. Es sind die Montagehinweise des Ventilherstellers zu beachten.', 'seed'),
  ('725', 'Bei Fahrzeugen mit einer bauartbedingten Höchstgeschwindigkeit über 210 km/h sind nur Metallschraubventile zulässig. Es sind die Montagehinweise des Ventilherstellers zu beachten.', 'seed'),
  ('73C', 'Es ist nur die Verwendung von schlauchlosen Reifen zulässig.', 'seed'),
  ('74A', 'Es dürfen nur die vom Radhersteller mitzuliefernden Radbefestigungsteile verwendet werden, dabei ist die Gewindegröße der serienmäßigen Befestigungsteile zu beachten. Bei Verwendung von Radschrauben, ist die, in der Anlage zum Gutachten, dem Fahrzeug zugeordnete Schaftlänge zu beachten.', 'seed'),
  ('74P', 'Radausführungen mit Zentrierring im Mittenloch sind nur zulässig, wenn die im Gutachten beschriebenen Zentrierringe verwendet werden.', 'seed'),
  ('76O', 'Die Verwendung dieser Radgröße ist nicht zulässig an Fahrzeugausführungen, die serienmäßig mit mindestens 19-Zoll-Rädern ausgerüstet sind.', 'seed'),
  ('76Z', 'Die Verwendung dieser Radgröße ist nur in Verbindung mit M+S-Reifen zulässig.', 'seed'),
  ('A01', 'Der vorschriftsmäßige Zustand des Fahrzeugs ist durch einen amtlich anerkannten Sachverständigen oder Prüfer für den Kraftfahrzeugverkehr oder einen Kraftfahrzeugsachverständigen oder einen Angestellten nach Nummer 4 der Anlage VIIIb zur StVZO auf einem Nachweis entsprechend dem im Beispielkatalog zum §19 StVZO veröffentlichten Muster bescheinigen zu lassen.', 'seed'),
  ('A02', 'Wird eine in diesem Gutachten aufgeführte Reifengröße verwendet, die nicht bereits in den Fahrzeugpapieren (u. a. Fahrzeugschein, Zulassungsbescheinigung I oder COC-Papier) genannt ist, so sind die Angaben über die Reifengröße in den Fahrzeugpapieren (Fahrzeugschein bzw. -brief, Zulassungsbescheinigung I) durch die Zulassungsstelle unter Vorlage der Allgemeinen Betriebserlaubnis bzw. der Abnahmebestätigung nach §19 Abs. 3 der StVZO berichtigen zu lassen. Diese Berichtigung ist dann nicht erforderlich, wenn die ABE des Sonderrades eine Freistellung von der Pflicht zur Berichtigung der Fahrzeugpapiere enthält.', 'seed'),
  ('A04', 'Die mindestens erforderlichen Geschwindigkeitsbereiche und Tragfähigkeiten der zu verwendenden Reifen, mit Ausnahme der M+S-Profile, sind den Fahrzeugpapieren (Fahrzeugbrief und -schein, Zulassungsbescheinigung I) zu entnehmen. Ferner sind nur Reifen eines Reifenherstellers und achsweise eines Profiltyps zulässig. Bei Verwendung unterschiedlicher Profiltypen auf Vorder- und Hinterachse ist die Eignung für das jeweilige Fahrzeug durch den Reifen- oder Fahrzeughersteller zu bestätigen. Diese Bestätigung ist vom Führer des Fahrzeugs mitzuführen.', 'seed'),
  ('A05', 'Das Fahrwerk und die Bremsaggregate müssen, mit Ausnahme der in der entsprechenden Auflage aufgeführten Umrüstmaßnahmen, dem Serienstand entsprechen. Die Zulässigkeit weiterer Veränderungen ist gesondert zu beurteilen.', 'seed'),
  ('A07', 'Zur Befestigung der Sonderräder dürfen nur die Serien-Radschrauben bzw. die Serien-Radmuttern verwendet werden, die in der Tabelle "Befestigungsmittel" (Seite 1) aufgeführt sind.', 'seed'),
  ('A08', 'Wird das serienmäßige Ersatzrad verwendet, soll mit mäßiger Geschwindigkeit und nicht länger als erforderlich gefahren werden. Es müssen die serienmäßigen Befestigungsteile verwendet werden. Bei Fahrzeugen mit Allradantrieb darf nur ein Ersatzrad mit gleicher Reifengröße bzw. gleichem Abrollumfang verwendet werden.', 'seed'),
  ('A09', 'Die Bezieher der Sonderräder sind darauf hinzuweisen, dass der vom Reifenhersteller vorgeschriebene Reifenfülldruck zu beachten ist.', 'seed'),
  ('A10', 'Es dürfen nur feingliedrige Schneeketten, die nicht mehr als 15 mm einschließlich Kettenschloss auftragen, an der Hinterachse verwendet werden.', 'seed'),
  ('A12', 'Die Verwendung von Schneeketten ist nicht zulässig.', 'seed'),
  ('A32', 'Es dürfen nur feingliedrige Schneeketten, die nicht mehr als 12 mm einschließlich Kettenschloss auftragen, an der Hinterachse verwendet werden.', 'seed'),
  ('A56', 'Die Rad/Reifen-Kombination ist nur zulässig an Fahrzeugausführungen mit Allradantrieb (z.B. 4WD, Quattro, Syncro, 4-Matic, 4x4 u.ä.)', 'seed'),
  ('A58', 'Rad-Reifen-Kombination(en) nicht zulässig an Fahrzeugen mit Allradantrieb.', 'seed'),
  ('A84', 'Die Vorgaben und Hinweise des Fahrzeugherstellers bezüglich der Verwendung von Winterreifen (M+S-Profil) und Schneeketten sind zu beachten (s. Betriebsanleitung).', 'seed'),
  ('A90', 'Es dürfen nur feingliedrige Schneeketten, die nicht mehr als 9 mm einschließlich Kettenschloss auftragen, an den laut Betriebsanleitung dafür vorgesehenen Achsen verwendet werden.', 'seed'),
  ('B03', 'Die Zulässigkeit der Sonderräder ist nicht geprüft für Fahrzeuge, die serienmäßig ausschließlich mit größeren und/oder breiteren Serienrädern für Sommerbereifung (nicht M+S Reifen) ausgerüstet sind (u. a. Fahrzeugschein, Zulassungsbescheinigung I, COC-Papier oder Bedienungsanleitung).', 'seed'),
  ('CAR', 'Die Rad/Reifen-Kombination ist zulässig für Fahrzeugausführungen der Aufbauart Kombilimousine (Avant, Break, Caravan, Kombi, Station-Wagon, Tourer, Turnier, Touring,..).', 'seed'),
  ('CBO', 'Die Rad/Reifen-Kombination ist zulässig für Fahrzeugausführungen der Aufbauart Cabriolet, Roadster.', 'seed'),
  ('CPE', 'Die Rad/Reifen-Kombination ist zulässig für Fahrzeugausführungen der Aufbauart Coupé.', 'seed'),
  ('F40', 'Rad/Reifenkombination nur zulässig an Fahrzeugausführungen mit Luftfederung an Achse 2.', 'seed'),
  ('FLH', 'Die Rad/Reifen-Kombination ist zulässig für Fahrzeugausführungen der Aufbauart Fließheck (3-türig und 5-türig).', 'seed'),
  ('K1A', 'Die Radabdeckung an Achse 1 ist durch Ausstellen der Frontschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 0° bis 30° vor Radmitte herzustellen. Die gesamte Breite der Rad-/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('K1B', 'Die Radabdeckung an Achse 1 ist durch Ausstellen des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 0° bis 50° hinter Radmitte herzustellen. Die gesamte Breite der Rad-/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('K1C', 'Die Radabdeckung an Achse 1 ist durch Ausstellen der Frontschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 30° vor bis 50° hinter Radmitte herzustellen. Die gesamte Breite der Rad-/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('K2B', 'Die Radabdeckung an Achse 2 ist durch Ausstellen der Heckschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 0° bis 50° hinter Radmitte herzustellen. Die gesamte Breite der Rad-/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('K2C', 'Die Radabdeckung an Achse 2 ist durch Ausstellen der Heckschürze und des Kotflügels oder durch Anbau von dauerhaft befestigten Karosserieteilen im Bereich 30° vor bis 50° hinter Radmitte herzustellen. Die gesamte Breite der Rad-/Reifenkombination muss, unter Beachtung des maximal möglichen Betriebsmaßes des Reifens (1,04 fache der Nennbreite des Reifens), in dem oben genannten Bereich abgedeckt sein.', 'seed'),
  ('K41', 'An Achse 1 ist durch Nacharbeiten der Radhausausschnittkanten eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen.', 'seed'),
  ('K42', 'An Achse 2 ist durch Nacharbeiten der Radhausausschnittkanten eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen.', 'seed'),
  ('K43', 'An Achse 1 ist durch Aufweiten der Kotflügel bzw. inneren Seitenteile eine ausreichende Freigängigkeit der Rad-Reifen-Kombination herzustellen.', 'seed'),
  ('K44', 'An Achse 2 ist durch Aufweiten der Kotflügel bzw. inneren Seitenteile eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen.', 'seed'),
  ('K45', 'An Achse 1 ist durch Nacharbeiten der Radhausinnenkotflügel, Kunststoffeinsätze bzw. deren Befestigungsteile eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen. Ein evtl. vorhandener Spritzschutz für den Ansaugweg des Luftfilters muss erhalten bleiben.', 'seed'),
  ('K46', 'An Achse 2 ist durch Nacharbeiten der Radhausinnenkotflügel, Kunststoffeinsätze bzw. deren Befestigungsteile eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen.', 'seed'),
  ('K4I', 'An Achse 2 ist die Radhausinnenverkleidung an der Radhausausschnittkante auszuschneiden bzw. um 5 mm zu kürzen und anschließend dauerhaft neu zu befestigen.', 'seed'),
  ('K56', 'Durch Nacharbeit der Heckschürze am Übergang zum Radhausausschnitt ist eine ausreichende Freigängigkeit der Rad-Reifenkombination herzustellen.', 'seed'),
  ('K6A', 'An Achse 2 sind die Radhausausschnittkanten im Bereich 100 mm vor bis 100 mm hinter Radmitte vollständig umzulegen.', 'seed'),
  ('K6V', 'An Achse 2 sind die Radhausausschnittkanten im Bereich 100 mm vor bis 100 mm hinter Radmitte um 5 mm auszuschneiden bzw. zu kürzen.', 'seed'),
  ('L02', 'Durch Begrenzung des Lenkeinschlages ist eine ausreichende Freigängigkeit der Rad- / Reifenkombination herzustellen.', 'seed'),
  ('L04', 'Die Verwendung dieser Rad/Reifen-Kombination(en) ist(sind) nur zulässig an Fahrzeugen mit Allradlenkung (4WS).', 'seed'),
  ('L05', 'Die Verwendung dieser Rad/Reifen-Kombination(en) ist(sind) nicht zulässig an Fahrzeugen mit Allradlenkung (4WS).', 'seed'),
  ('L06', 'Diese Rad/Reifen-Kombination(en) ist (sind) zulässig an Fahrzeugausführungen mit und ohne Allradlenkung (4WS).', 'seed'),
  ('LIM', 'Die Rad/Reifen-Kombination ist zulässig für Fahrzeugausführungen der Aufbauart Limousine.', 'seed'),
  ('NBF', 'Das Sonderrad ist nicht zulässig für gepanzerte bzw. beschussgeschützte Fahrzeugausführungen.', 'seed'),
  ('R02', 'Diese Reifengröße ist nur an Achse 1 zulässig.', 'seed'),
  ('R03', 'Diese Reifengröße ist nur an Achse 2 zulässig.', 'seed'),
  ('R09', 'Diese Reifengröße ist nur zulässig, wenn sie bereits als Serienbereifung freigegeben ist (Fahrzeugschein, Zulassungsbescheinigung I oder COC-Papier).', 'seed'),
  ('R21', 'Es können Reifen gleicher Größe verwendet werden, die gemäß Bestätigung des Reifenherstellers auf der im Gutachten genannten Radgröße montierbar sind und ausreichende Tragfähigkeit bei max. Sturzwinkel und Höchstgeschwindigkeit aufweisen. Diese Bestätigung ist vom Führer des Fahrzeugs mitzuführen.', 'seed'),
  ('R35', 'Bei dieser Serien-Reifengröße sind die Empfehlungen des Fahrzeugherstellers zu beachten (u. a. Fahrzeugschein, Zulassungsbescheinigung I, COC-Papier oder Bedienungsanleitung).', 'seed'),
  ('R37', 'Diese Reifengröße ist nicht geprüft für Fahrzeuge, die serienmäßig ausschließlich mit größeren und/oder breiteren Reifengrößen (u. a. Fahrzeugschein, Zulassungsbescheinigung I, COC-Papier oder Bedienungsanleitung) ausgerüstet sind.', 'seed'),
  ('R70', 'Für das Fahrzeug ist die Reifengröße auf der im Gutachten genannten Radgröße durch den Reifenhersteller zu bestätigen. Diese Bestätigung ist vom Führer des Fahrzeugs mitzuführen.', 'seed'),
  ('S01', 'Zur Befestigung der Sonderräder dürfen nur die mitgelieferten Befestigungsmittel Nr. S01 (siehe Seite 1) verwendet werden.', 'seed'),
  ('S02', 'Zur Befestigung der Sonderräder dürfen nur die mitgelieferten Befestigungsmittel Nr. S02 (siehe Seite 1) verwendet werden.', 'seed'),
